import numpy as np


class RefinedArchiveJADEPatternESv10:
    """
    Mixed-integer (mu+lambda) evolution with adaptive constraint-weighted feasibility rules.

    Key ideas:
      * JADE-style current-to-pbest DE with success-adapted F/CR and an external
        archive, competing with a Gaussian self-adaptive operator;
      * adaptive constraint weighting: each constraint keeps an exponential
        moving average of how often it is violated, and infeasible individuals
        are ranked by a weighted violation sum, so frequently violated
        constraints are handled explicitly. Feasibility itself is unchanged;
      * restarts triggered by population collapse, generation stagnation, or a
        global evaluation-based stagnation counter;
      * IPOP-style population doubling on every second restart;
      * restart seeds mix stratified random points, archive perturbations and
        multi-scale perturbations of the global best;
      * compass polishing of archive elites and a final polish of the global best.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)
        self.mu0 = max(10, min(40, 3 * self.dim))
        self.p_cross = 0.7
        self.p_resample_ordinal = 0.15
        self.stall_limit = 8
        self.ls_stall = 2
        self.polish_frac = 0.05
        self.archive_size = 20
        self.sigmas = np.array([0.2, 0.05, 0.01])
        self.jade_c = 0.1
        self.spread_tol = 1e-3
        self.final_frac = 0.15
        self.weight_gain = 4.0
        self.rate_decay = 0.99

    def __call__(self, func):
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        dim = len(lb)
        vtypes = [str(t) for t in func.variable_types]
        nv = np.ones(dim, dtype=int)
        for i, t in enumerate(vtypes):
            if t != "continuous":
                nv[i] = int(func.n_values[i])
        is_int = np.array([t != "continuous" for t in vtypes])
        is_ord = np.array([t == "ordinal" for t in vtypes])
        ii = np.where(is_int)[0]
        ci = np.where(~is_int)[0]
        span = ub - lb
        pm = min(1.0, 2.0 / dim)
        tau = 1.0 / np.sqrt(2.0 * np.sqrt(max(1, dim)))
        cmask_all = np.zeros(dim, dtype=bool)
        cmask_all[ci] = True

        state = {"evals": 0, "best_f": np.inf, "best_x": None,
                 "best_ind": None, "last_imp": 0}
        archive = []
        ext = []
        succ = np.zeros(2)
        tot = np.zeros(2)
        jade = {"muF": 0.6, "muCR": 0.8}
        polish = {"frac": self.polish_frac}
        sig_gain = np.ones(len(self.sigmas))
        sig_use = np.ones(len(self.sigmas)) * 2.0
        restarts = {"n": 0}
        size = {"mu": self.mu0}
        final_done = {"v": False}
        # adaptive constraint weights: rate = EMA of violation indicator
        wts = {"rate": None, "w": None}

        def repair(x):
            x = np.array(x, dtype=float)
            if len(ci):
                x[ci] = np.clip(x[ci], lb[ci], ub[ci])
            if len(ii):
                x[ii] = np.clip(np.rint(x[ii]), 0, nv[ii] - 1)
            return x

        def stratified_points(n):
            pts = [np.empty(dim) for _ in range(n)]
            for p in pts:
                if len(ii):
                    p[ii] = np.floor(np.random.rand(len(ii)) * nv[ii])
            if len(ci):
                for k in ci:
                    perm = np.random.permutation(n)
                    u = (perm + np.random.rand(n)) / n
                    vals = lb[k] + u * span[k]
                    for t in range(n):
                        pts[t][k] = vals[t]
            return [repair(p) for p in pts]

        def update_archive(ind):
            for a in archive:
                if np.array_equal(a["x"], ind["x"]):
                    return
            archive.append(ind)
            archive.sort(key=lambda a: a["f"])
            del archive[self.archive_size:]

        def update_weights(g):
            if wts["rate"] is None or len(wts["rate"]) != len(g):
                wts["rate"] = np.zeros(len(g))
            wts["rate"] = self.rate_decay * wts["rate"] + (1.0 - self.rate_decay) * (g > 0).astype(float)
            wts["w"] = 1.0 + self.weight_gain * wts["rate"]

        def ev(x, s=0.1):
            if state["evals"] >= self.budget:
                return None
            x = repair(x)
            f, g = func(x)
            state["evals"] += 1
            f = float(f)
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(),
                              nan=1e6, posinf=1e6, neginf=-1e6)
            g = np.maximum(g, 0.0)
            finite = np.isfinite(f)
            extra = 0.0
            if not finite:
                f = np.inf
                extra = 1.0
            feas = finite and float(np.sum(g)) <= 0.0
            if len(g):
                update_weights(g)
            ind = {"x": x, "f": f, "g": g, "extra": extra,
                   "v": float(np.sum(g)) + extra, "feas": feas, "s": float(s)}
            if feas:
                update_archive(ind)
                if f < state["best_f"] - 1e-12:
                    state["last_imp"] = state["evals"]
                if f < state["best_f"]:
                    state["best_f"] = f
                    state["best_x"] = x.copy()
                    state["best_ind"] = ind
            return ind

        def key(ind):
            if ind["feas"]:
                return (0, ind["f"])
            gg = ind["g"]
            if wts["w"] is None or len(wts["w"]) != len(gg):
                wv = float(np.sum(gg))
            else:
                wv = float(np.dot(wts["w"], gg))
            return (1, wv + ind["extra"])

        def spread(pop):
            X = np.array([p["x"] for p in pop])
            parts = []
            if len(ci):
                parts.append(np.mean(np.std(X[:, ci] / np.maximum(span[ci], 1e-12), axis=0)))
            if len(ii):
                denom = np.maximum(nv[ii] - 1, 1)
                parts.append(np.mean(np.std(X[:, ii] / denom, axis=0)))
            return float(np.mean(parts)) if parts else 0.0

        def tournament(pop):
            i, j = np.random.randint(len(pop)), np.random.randint(len(pop))
            return pop[i] if key(pop[i]) <= key(pop[j]) else pop[j]

        def mutate_ints(child):
            for k in ii:
                if np.random.rand() < pm:
                    if is_ord[k] and np.random.rand() >= self.p_resample_ordinal:
                        child[k] += np.random.choice([-1.0, 1.0])
                    else:
                        child[k] = np.floor(np.random.rand() * nv[k])
            return child

        def p_de():
            rates = (succ + 1.0) / (tot + 2.0)
            p = rates[0] / (rates[0] + rates[1])
            return float(np.clip(p, 0.2, 0.8))

        def muF_draw():
            return jade["muF"] + 0.1 * np.random.standard_cauchy()

        def make_child(pop, pool):
            p1 = tournament(pop)
            p2 = tournament(pop)
            F = CR = None
            if len(ci) > 0 and len(pop) >= 4 and np.random.rand() < p_de():
                op = 0
                n_top = max(2, int(0.15 * len(pop)))
                pb = pop[np.random.randint(n_top)]
                r1 = pop[np.random.randint(len(pop))]
                r2 = pool[np.random.randint(len(pool))]
                F = float(np.clip(muF_draw(), 0.1, 1.0))
                CR = float(np.clip(np.random.normal(jade["muCR"], 0.1), 0.0, 1.0))
                donor = p1["x"] + F * (pb["x"] - p1["x"]) + F * (r1["x"] - r2["x"])
                child = p1["x"].copy()
                mask = np.random.rand(dim) < CR
                mask[ci[np.random.randint(len(ci))]] = True
                sel = mask & cmask_all
                child[sel] = donor[sel]
                s = p1["s"]
            else:
                op = 1
                s = float(np.clip(p1["s"] * np.exp(tau * np.random.normal()), 1e-3, 0.5))
                if np.random.rand() < self.p_cross:
                    cm = np.random.rand(dim) < 0.5
                    child = np.where(cm, p1["x"], p2["x"]).astype(float)
                else:
                    child = p1["x"].copy()
                for k in ci:
                    if np.random.rand() < max(pm, 1.0 / max(1, len(ci))):
                        z = np.random.standard_cauchy() if np.random.rand() < 0.1 else np.random.normal()
                        child[k] += s * span[k] * 0.5 * np.clip(z, -5.0, 5.0)
            child = mutate_ints(child)
            return repair(child), s, op, p1, F, CR

        def compass(start, cap):
            cur = start
            origin = start
            h = np.zeros(dim)
            h[ci] = 0.05 * span[ci]
            spent = 0
            while spent < cap and len(ci) > 0 and np.max(h[ci]) > 1e-6:
                improved = False
                moves = [(k, sg) for k in ci for sg in (1.0, -1.0)]
                np.random.shuffle(moves)
                for k, sg in moves:
                    if spent >= cap:
                        break
                    y = cur["x"].copy()
                    y[k] += sg * h[k]
                    ind = ev(y, cur["s"])
                    if ind is None:
                        return cur
                    spent += 1
                    if key(ind) < key(cur):
                        cur = ind
                        h[k] = min(h[k] * 2.0, 0.5 * span[k])
                        improved = True
                        break
                if not improved:
                    for _ in range(2):
                        if spent >= cap:
                            break
                        y = cur["x"].copy()
                        y[ci] += h[ci] * np.random.normal(size=len(ci))
                        ind = ev(y, cur["s"])
                        if ind is None:
                            return cur
                        spent += 1
                        if key(ind) < key(cur):
                            cur = ind
                            improved = True
                            break
                if improved and spent < cap and np.any(cur["x"] != origin["x"]):
                    d = cur["x"] - origin["x"]
                    y = repair(cur["x"] + d)
                    if not np.array_equal(y, cur["x"]):
                        ind = ev(y, cur["s"])
                        if ind is None:
                            return cur
                        spent += 1
                        if key(ind) < key(cur):
                            cur = ind
                    origin = cur
                if not improved:
                    h[ci] *= 0.5
            for k in ii:
                if spent >= cap:
                    break
                if is_ord[k]:
                    cands = [cur["x"][k] + 1.0, cur["x"][k] - 1.0]
                else:
                    if nv[k] <= 1:
                        continue
                    alts = [v for v in range(nv[k]) if v != int(cur["x"][k])]
                    np.random.shuffle(alts)
                    cands = [float(v) for v in alts[:2]]
                for val in cands:
                    if spent >= cap:
                        break
                    y = cur["x"].copy()
                    y[k] = val
                    ind = ev(y, cur["s"])
                    if ind is None:
                        return cur
                    spent += 1
                    if key(ind) < key(cur):
                        cur = ind
                        break
            return cur

        def archive_seed(sigma):
            n = len(archive)
            r = min(int(np.random.exponential(max(1.0, n / 4.0))), n - 1)
            base = archive[r]["x"]
            x = base.copy()
            if len(ci):
                x[ci] = x[ci] + sigma * span[ci] * np.random.normal(size=len(ci))
            for k in ii:
                if np.random.rand() < 0.1:
                    x[k] = np.floor(np.random.rand() * nv[k])
            return repair(x)

        def best_perturb(scale):
            x = state["best_x"].copy()
            if len(ci):
                x[ci] = x[ci] + scale * span[ci] * np.random.normal(size=len(ci))
            for k in ii:
                if np.random.rand() < 0.05:
                    x[k] = np.floor(np.random.rand() * nv[k])
            return repair(x)

        def pick_sigma():
            p = sig_gain / sig_use
            p = p / np.sum(p)
            p = 0.8 * p + 0.2 / len(p)
            return int(np.random.choice(len(p), p=p))

        def patience():
            return int(min(30, self.stall_limit * (1.0 + 0.5 * restarts["n"])))

        def stale_limit():
            # tighter global evaluation-based stagnation threshold
            return max(12 * size["mu"], 0.04 * self.budget)

        # ---- initial population ----
        mu = size["mu"]
        pop = []
        n0 = min(self.budget, 4 * mu)
        for x0 in stratified_points(n0):
            ind = ev(x0)
            if ind is None:
                break
            pop.append(ind)
        if not pop:
            return state["best_f"], state["best_x"]
        pop = sorted(pop, key=key)[:mu]

        best_key_hist = key(pop[0])
        stall = 0

        while state["evals"] < self.budget:
            remaining = self.budget - state["evals"]
            if (not final_done["v"] and state["best_ind"] is not None
                    and remaining <= self.final_frac * self.budget):
                final_done["v"] = True
                cap = remaining // 2
                if cap > 0:
                    polished = compass(state["best_ind"], cap)
                    if polished is not None:
                        pop = sorted(pop + [polished], key=key)[:size["mu"]]
                continue

            mu = size["mu"]
            lam = mu
            pool = pop + ext if ext else pop
            sF, sCR = [], []
            children = []
            replaced = []
            for _ in range(lam):
                if state["evals"] >= self.budget:
                    break
                x, s, op, p1, F, CR = make_child(pop, pool)
                pk = key(p1)
                c = ev(x, s)
                if c is None:
                    break
                tot[op] += 1
                if key(c) < pk:
                    succ[op] += 1
                    if op == 0:
                        sF.append(F)
                        sCR.append(CR)
                        replaced.append(p1)
                children.append(c)
            if not children:
                break
            succ *= 0.9
            tot *= 0.9

            if sF:
                sF_arr = np.asarray(sF)
                lehmer = float(np.sum(sF_arr ** 2) / max(np.sum(sF_arr), 1e-12))
                c_ = self.jade_c
                jade["muF"] = (1 - c_) * jade["muF"] + c_ * lehmer
                jade["muCR"] = (1 - c_) * jade["muCR"] + c_ * float(np.mean(sCR))

            ext.extend({"x": r["x"]} for r in replaced)
            if len(ext) > len(pop):
                np.random.shuffle(ext)
                del ext[len(pop):]

            pop = sorted(pop + children, key=key)[:mu]

            cur = key(pop[0])
            if cur < best_key_hist:
                best_key_hist = cur
                stall = 0
            else:
                stall += 1

            # compass polishing of a rank-biased top-3 archive elite
            if stall >= self.ls_stall and archive and state["evals"] < self.budget:
                cap = max(2 * dim + 4, int(polish["frac"] * self.budget))
                cap = min(cap, self.budget - state["evals"])
                if cap > 0:
                    elite = archive[np.random.randint(min(3, len(archive)))]
                    ekey = key(elite)
                    polished = compass(elite, cap)
                    if key(polished) < ekey:
                        polish["frac"] = min(0.3, polish["frac"] * 1.5)
                    else:
                        polish["frac"] = max(0.02, polish["frac"] * 0.7)
                    pop = sorted(pop + [polished], key=key)[:mu]
                    cur = key(pop[0])
                    if cur < best_key_hist:
                        best_key_hist = cur
                    stall = 0

            collapsed = len(pop) >= 4 and spread(pop) < self.spread_tol
            global_stale = (state["best_x"] is not None and
                            state["evals"] - state["last_imp"] > stale_limit())
            if ((stall >= patience()) or collapsed or global_stale) \
                    and state["evals"] < self.budget:
                restarts["n"] += 1
                size["mu"] = int(min(4 * self.mu0, self.mu0 * 2 ** (restarts["n"] // 2)))
                mu_new = size["mu"]
                p_arch = max(0.2, 0.8 - 0.1 * restarts["n"])
                keep = pop[:1]
                si = pick_sigma()
                sigma = self.sigmas[si]
                sig_use[si] += 1.0
                before = key(keep[0])
                new = []
                n_new = mu_new - len(keep)
                rand_seeds = iter(stratified_points(n_new))
                n_best = min(3, max(0, n_new // 5)) if state["best_x"] is not None else 0
                scales = [0.03, 0.003, 0.01]
                for t in range(n_new):
                    if state["evals"] >= self.budget:
                        break
                    if t < n_best:
                        ind = ev(best_perturb(scales[t % len(scales)]), sigma)
                    elif archive and np.random.rand() < p_arch:
                        ind = ev(archive_seed(sigma), sigma)
                    else:
                        ind = ev(next(rand_seeds), 0.2)
                    if ind is None:
                        break
                    new.append(ind)
                if not new:
                    break
                pop = sorted(keep + new, key=key)[:mu_new]
                if min(key(n) for n in new) < before:
                    sig_gain[si] += 1.0
                ext = []
                stall = 0
                best_key_hist = key(pop[0])

        return float(state["best_f"]), (None if state["best_x"] is None else state["best_x"])
